const params = new URLSearchParams(location.search);
document.body.classList.add(params.get('theme') === 'light' ? 'light' : 'dark');
const cards = [{name:'qwen3:8b',status:'Loaded',size:'5.2 GiB',runtime:'Ollama'},{name:'llama3.1:8b',status:'Loaded',size:'4.9 GiB',runtime:'Ollama'},{name:'mistral:7b',status:'Unloaded',size:'4.1 GiB',runtime:'Ollama'}];
const cardMarkup = m => `<article class="frosted model-card" data-name="${m.name}"><div class="model-top"><h3>${m.name}</h3><span class="badge ${m.status==='Unloaded'?'unloaded':''}">${m.status}</span></div><p>Local model · ${m.runtime}</p><div class="model-facts"><span>Size <b>${m.size}</b></span><span>Context <b>32K</b></span></div><button class="details-button">Details</button></article>`;
document.querySelector('.preview').innerHTML = cards.slice(0,2).map(cardMarkup).join('');
document.querySelector('.full').innerHTML = cards.map(cardMarkup).join('');
const dialog=document.querySelector('dialog');
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){let name=view.dataset.view;document.querySelector('#overview').hidden=name!=='overview';document.querySelector('#models').hidden=name!=='models';const titles={overview:'Overview',models:'Model Manager',library:'Model Library',workspaces:'Workspaces',activity:'Activity',settings:'Settings'};document.querySelector('#placeholder').hidden=name==='overview'||name==='models';document.querySelector('#page-title').textContent=titles[name];document.querySelector('#location').textContent=titles[name].toUpperCase();document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===name);if(n.dataset.view===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')});}if(e.target.closest('.details-button')){const model=cards.find(m=>m.name===e.target.closest('.model-card').dataset.name);dialog.querySelector('.dialog-body h3').textContent=model.name;const badge=dialog.querySelector('.dialog-body .badge');badge.textContent=model.status;badge.classList.toggle('unloaded',model.status==='Unloaded');dialog.querySelectorAll('.detail-row b')[1].textContent=model.size;dialog.showModal();}if(e.target.closest('#close'))dialog.close();});
if(params.get('view')==='models' || params.get('view')==='details')document.querySelector('.nav[data-view="models"]').click();
if(params.get('view')==='details')dialog.showModal();

dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[dialog.querySelector('#close'),dialog.querySelector('.dialog-body')];if(e.shiftKey && (document.activeElement===items[0]||document.activeElement===dialog.querySelector('#dialog-title'))){e.preventDefault();items[1].focus();}else if(!e.shiftKey && document.activeElement===items[1]){e.preventDefault();items[0].focus();}});

const nav=document.querySelector('nav');const hint=document.querySelector('.nav-hint');function updateHint(){hint.hidden=nav.scrollWidth-nav.clientWidth-nav.scrollLeft<2;}nav.addEventListener('scroll',updateHint,{passive:true});window.addEventListener('resize',updateHint);updateHint();
nav.addEventListener('focusin',e=>{if(!matchMedia('(max-width: 650px)').matches)return;const item=e.target.getBoundingClientRect(),box=nav.getBoundingClientRect();if(item.left<box.left+4)nav.scrollLeft+=item.left-box.left-4;else if(item.right>box.right-4)nav.scrollLeft+=item.right-box.right+4;});
